// AWS SigV4 presigned URL for RustFS (path-style). Self-contained.
// REQUIRES one of:
//   * the Code-node sandbox exposes global WebCrypto (Node 20 `crypto.subtle`), or
//   * the n8n container has NODE_FUNCTION_ALLOW_BUILTIN=crypto
// Input JSON: { method:'GET'|'PUT', bucket, object_key, expires_seconds,
//               endpoint, region, access_key_id, secret_access_key }
// NOTE: passing the secret as workflow input is a foot-gun. Prefer generating
// presigned URLs in the service that already holds the RustFS key.

const inp = $input.first().json;
const region = inp.region || 'us-east-1';
const service = 's3';
const method = (inp.method || 'GET').toUpperCase();
const endpoint = (inp.endpoint || 'http://rustfs:9000').replace(/\/+$/, '');
const bucket = inp.bucket;
const key = inp.object_key;
const expires = Math.min(parseInt(inp.expires_seconds || 900, 10), 604800);
const accessKeyId = inp.access_key_id;
const secretAccessKey = inp.secret_access_key;
if (!bucket || !key || !accessKeyId || !secretAccessKey) {
  throw new Error('bucket, object_key, access_key_id, secret_access_key are required');
}

let subtle;
if (typeof crypto !== 'undefined' && crypto.subtle) {
  subtle = crypto.subtle;
} else {
  subtle = require('crypto').webcrypto.subtle;
}
const enc = new TextEncoder();
const host = new URL(endpoint).host;
const amzDate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, '');
const dateStamp = amzDate.slice(0, 8);
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
async function sha256Hex(s) { return hex(await subtle.digest('SHA-256', enc.encode(s))); }
async function hmac(keyBytes, msg) {
  const k = await subtle.importKey('raw', keyBytes, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await subtle.sign('HMAC', k, enc.encode(msg)));
}

const uriPath = '/' + encodeURIComponent(bucket) + '/' + key.split('/').map(encodeURIComponent).join('/');
const scope = `${dateStamp}/${region}/${service}/aws4_request`;
const params = {
  'X-Amz-Algorithm': 'AWS4-HMAC-SHA256',
  'X-Amz-Credential': `${accessKeyId}/${scope}`,
  'X-Amz-Date': amzDate,
  'X-Amz-Expires': String(expires),
  'X-Amz-SignedHeaders': 'host',
};
const canonicalQuery = Object.keys(params).sort()
  .map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(params[k])}`).join('&');
const canonicalRequest = [method, uriPath, canonicalQuery, `host:${host}\n`, 'host', 'UNSIGNED-PAYLOAD'].join('\n');
const stringToSign = ['AWS4-HMAC-SHA256', amzDate, scope, await sha256Hex(canonicalRequest)].join('\n');

let k = enc.encode('AWS4' + secretAccessKey);
for (const part of [dateStamp, region, service, 'aws4_request']) k = await hmac(k, part);
const signature = hex(await hmac(k, stringToSign));

const url = `${endpoint}${uriPath}?${canonicalQuery}&X-Amz-Signature=${signature}`;
return [{ json: {
  url, method, bucket, object_key: key,
  expires_seconds: expires,
  expires_at: new Date(Date.now() + expires * 1000).toISOString(),
} }];
